-- Revertir doble codificación UTF-8 (AndrÃ©s -> Andrés) en todas las columnas de texto
-- Detecta filas con bytes C383 (Ã) o C282 (Â) y aplica latin1->utf8mb4 round-trip
-- Fecha: 2026-08-11
SET NAMES utf8mb4;

UPDATE `alertas_desviacion` SET `descripcion` = CONVERT(CAST(CONVERT(`descripcion` USING latin1) AS BINARY) USING utf8mb4), `notas_resolucion` = CONVERT(CAST(CONVERT(`notas_resolucion` USING latin1) AS BINARY) USING utf8mb4) WHERE HEX(`descripcion`) LIKE '%C383%' OR HEX(`descripcion`) LIKE '%C282%' OR HEX(`notas_resolucion`) LIKE '%C383%' OR HEX(`notas_resolucion`) LIKE '%C282%';
